import { boolean, index, pgTable, text, timestamp } from "drizzle-orm/pg-core";

/**
 * Tables owned by Better Auth (people signing in). Columns mirror Better
 * Auth's core schema (`getSchema` from `better-auth/db`, v1.7) plus our
 * additional fields; don't rename them without checking Better Auth's model.
 * Ids are strings generated by Better Auth.
 *
 * Agents are NOT users: they live in `agents` (docs/adr/0006-auth-and-tenancy.md).
 */
export const users = pgTable("users", {
  id: text().primaryKey(),
  name: text().notNull(),
  email: text().notNull().unique(),
  emailVerified: boolean().notNull().default(false),
  image: text(),
  /** The app's language (a code of `@agenteschat/i18n/locale`): emails and pushes are written in it. */
  locale: text(),
  /**
   * The language follows each device's own ("Automático", the default) until the person picks one; the devices
   * then show that one everywhere (ADR 0122). Not a Better Auth field.
   */
  localeAuto: boolean().notNull().default(true),
  /**
   * Blocked by the people who run this server (operator API, ADR 0056): no sign-in and no membership
   * anywhere (`standing.ts`). Not a Better Auth field, so it never reaches a session or the cookie cache.
   */
  blockedAt: timestamp({ withTimezone: true }),
  blockedReason: text(),
  /**
   * Deleted by the person, gone for good at this date (ADR 0088 §10): until then it signs in only to the waiting
   * screen, and every membership check reads it as no member (`accountInUse`). Not a Better Auth field.
   */
  deletionDueAt: timestamp({ withTimezone: true }),
  deletionRequestedAt: timestamp({ withTimezone: true }),
  /**
   * The person's own area, asked once during the onboarding: an id of `WORK_AREAS`
   * (`@agenteschat/client/lib/work-area`) or `skipped`; null until asked. About the person, not a workspace, read by
   * the operator API's account (which kinds of people stay). Not a Better Auth field.
   */
  workArea: text(),
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
});

export const sessions = pgTable(
  "sessions",
  {
    id: text().primaryKey(),
    expiresAt: timestamp({ withTimezone: true }).notNull(),
    token: text().notNull().unique(),
    ipAddress: text(),
    userAgent: text(),
    userId: text()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    /** Organization the web app is showing in this session. Validated against memberships on every use. */
    activeOrganizationId: text(),
    createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index().on(t.userId)],
);

/** Sign-in methods of a user: `credential` (email + password) or a social provider. */
export const accounts = pgTable(
  "accounts",
  {
    id: text().primaryKey(),
    accountId: text().notNull(),
    providerId: text().notNull(),
    userId: text()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    accessToken: text(),
    refreshToken: text(),
    idToken: text(),
    accessTokenExpiresAt: timestamp({ withTimezone: true }),
    refreshTokenExpiresAt: timestamp({ withTimezone: true }),
    scope: text(),
    /** Password hash (scrypt, by Better Auth). */
    password: text(),
    createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index().on(t.userId)],
);

/** Short-lived tokens: email verification, password reset. */
export const verifications = pgTable(
  "verifications",
  {
    id: text().primaryKey(),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: timestamp({ withTimezone: true }).notNull(),
    createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index().on(t.identifier)],
);
